import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func isPrime(num int) bool {
	if num <= 1 {
		return false
	}
	for i := 2; i*i <= num; i++ {
		if num%i == 0 {
			return false
		}
	}
	return true
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	line := scanner.Text()
	parts := strings.Fields(line)
	if len(parts) < 2 {
		return
	}
	n, _ := strconv.Atoi(parts[0])
	m, _ := strconv.Atoi(parts[1])

	for i := n + 1; i <= m; i++ {
		if isPrime(i) {
			if i != m {
				fmt.Println("NO")
				return
			} else {
				fmt.Println("YES")
				return
			}
		}
	}
	fmt.Println("NO")
}

